/bin/zsh -lc "python3 -B - <<'PY'
from inventory import reserve_many

for requested, expected_error in [
    ({'a': 2, 'missing': 1}, KeyError),
    ({'a': 2, 'b': 0}, ValueError),
    ({'a': 2, 'b': -1}, ValueError),
    ({'a': 2, 'b': 5}, ValueError),
]:
    stock = {'a': 5, 'b': 4, 'untouched': 9}
    before = stock.copy()
    try:
        reserve_many(stock, requested)
    except expected_error:
        pass
    else:
        raise AssertionError(f'Expected {expected_error.__name__}')
    assert stock == before, (stock, before)

stock = {'a': 5, 'b': 4, 'untouched': 9}
requested = {'a': 2, 'b': 4}
alias = stock
result = reserve_many(stock, requested)
assert stock is alias
assert stock == result == {'a': 3, 'b': 0, 'untouched': 9}
assert result is not stock
result['a'] = 99
assert stock['a'] == 3
assert requested == {'a': 2, 'b': 4}
result = reserve_many(stock, {})
assert result == stock and result is not stock
stock = {'a': 2, 'b': 3}
assert reserve_many(stock, stock) == {'a': 0, 'b': 0}
assert stock == {'a': 0, 'b': 0}
print('Passed: failure atomicity and exception types; in-place success; detached return; unrequested entries; empty and aliased requests.')
